(() => {
'use strict';
const surfaces = {"scapula":[527,""],"clavicle":[200,""],"humerus":[422,""],"radius":[250,""],"ulna":[283,""],"handOpen":[1755,""],"handGrip":[1755,""]};
function decode(T, key, side) {
  const [count, packed] = surfaces[key];
  const raw = atob(packed);
  const bytes = Uint8Array.from(raw, char => char.charCodeAt(0));
  const view = new DataView(bytes.buffer);
  const positions = new Float32Array(count * 3);
  const indices = new Uint16Array((bytes.length - count * 6) / 2);
  for (let i = 0; i < positions.length; i++) {
    positions[i] = view.getInt16(i * 2, true) / 16000 * (i % 3 === 0 ? side : 1);
  }
  for (let i = 0; i < indices.length; i++) indices[i] = view.getUint16((positions.length + i) * 2, true);
  if (side < 0) {
    for (let i = 0; i < indices.length; i += 3) [indices[i + 1], indices[i + 2]] = [indices[i + 2], indices[i + 1]];
  }
  const geometry = new T.BufferGeometry();
  geometry.setAttribute('position', new T.BufferAttribute(positions, 3));
  geometry.setIndex(new T.BufferAttribute(indices, 1));
  geometry.computeVertexNormals();
  return geometry;
}

window.azAttachUpperSkeleton = function(parts) {
  const {T, torso, sternum, arms, exArms, exerciseArms} = parts;
  const geometries = new Map();
  const down = new T.Vector3(0, -1, 0);
  const vector = (x, y, z) => new T.Vector3(x, y, z);
  function geometry(key, side = 1) {
    const id = key + side;
    if (!geometries.has(id)) geometries.set(id, decode(T, key, side));
    return geometries.get(id);
  }
  function add(parent, key, material, side = 1) {
    const mesh = new T.Mesh(geometry(key, side), material);
    mesh.name = 'BodyParts3D ' + key;
    parent.add(mesh);
    return mesh;
  }
  function discard(node) {
    node.removeFromParent();
    node.traverse(child => child.geometry?.dispose());
  }
  function clear(group) {
    for (const child of group.children.slice()) discard(child);
  }
  function mountSegment(parent, keys, start, end, material, side) {
    const frame = new T.Group();
    const delta = end.clone().sub(start);
    frame.position.copy(start);
    frame.quaternion.setFromUnitVectors(down, delta.clone().normalize());
    frame.scale.y = delta.length();
    for (const key of keys) add(frame, key, material, side);
    parent.add(frame);
  }

  // Track the actual posterolateral rib surface as the chest flexes. The
  // blade stays rigid, with its glenoid fixed at the shoulder throughout.
  function chestSurface(side) {
    const samples = [], point = new T.Vector3();
    for (let level=1; level<=9; level++) {
      const frame=parts.ribs[(level-1)*2+(side===1?1:0)], mesh=frame.children[0];
      const vertices=mesh.geometry.attributes.position, sectors=[];
      frame.updateMatrix();
      for (let index=0; index<vertices.count; index++) {
        point.fromBufferAttribute(vertices,index).applyMatrix4(frame.matrix);
        const x=point.x*side, z=point.z+.04;
        if (x<.18 || z>.04) continue;
        const sector=Math.floor((Math.atan2(-z,x)+.15)*10), radius=x*x+z*z;
        if (!sectors[sector] || radius>sectors[sector].radius) sectors[sector]={radius,index};
      }
      for (const cell of sectors) if (cell) samples.push({frame,vertices,index:cell.index,point:new T.Vector3()});
    }
    return samples;
  }
  function bladeContactPoints(shape,frame,side) {
    const cells=new Map(), point=new T.Vector3(), vertices=shape.attributes.position;
    for (let i=0; i<vertices.count; i++) {
      point.fromBufferAttribute(vertices,i).applyMatrix4(frame.matrix);
      if (point.y>.87 || point.x*side>.94) continue;
      const cell=Math.floor(point.y/.115)+','+Math.floor(point.x*side/.12);
      if (!cells.has(cell) || point.z>cells.get(cell).z) cells.set(cell,point.clone());
    }
    const inverse=frame.matrix.clone().invert();
    return [...cells.values()].map(p=>p.applyMatrix4(inverse));
  }
  const shift=new T.Vector3(), radial=new T.Vector3(), probe=new T.Vector3(), before=new T.Vector3();
  const axisX=vector(1,0,0), axisY=vector(0,1,0), axisZ=vector(0,0,1), increment=new T.Quaternion();
  function seatBlade(frame,pivot,ribs,markers) {
    for (const sample of ribs) {
      sample.frame.updateMatrix();
      sample.point.fromBufferAttribute(sample.vertices,sample.index).applyMatrix4(sample.frame.matrix);
    }
    for (let iteration=0; iteration<4; iteration++) {
      frame.updateMatrix(); before.copy(pivot).applyMatrix4(frame.matrix);
      let xx=.10, yy=.10, zz=.32, xy=0, xz=0, yz=0, bx=0, by=0, bz=0;
      for (const marker of markers) {
        probe.copy(marker).applyMatrix4(frame.matrix);
        let best=Infinity, nearest;
        for (const {point} of ribs) {
          const distance=point.distanceToSquared(probe);
          if (distance<best) {best=distance;nearest=point;}
        }
        if (!nearest) continue;
        radial.set(nearest.x,0,nearest.z+.04).normalize();
        const clearance=shift.copy(probe).sub(nearest).dot(radial);
        const error=.055-clearance, weight=clearance<.015?3:1;
        shift.copy(probe).sub(before);
        const dx=radial.z*shift.y, dy=radial.x*shift.z-radial.z*shift.x, dz=-radial.x*shift.y;
        xx+=weight*dx*dx; xy+=weight*dx*dy; yy+=weight*dy*dy;
        xz+=weight*dx*dz; yz+=weight*dy*dz; zz+=weight*dz*dz;
        bx+=weight*dx*error; by+=weight*dy*error; bz+=weight*dz*error;
      }
      const diagonal=zz-yz*yz/yy, mixed=xz-xy*yz/yy, xDiagonal=xx-xy*xy/yy;
      const xRhs=bx-xy*by/yy, zRhs=bz-yz*by/yy, determinant=xDiagonal*diagonal-mixed*mixed;
      const rawPitch=(diagonal*xRhs-mixed*zRhs)/determinant;
      const rawRoll=(xDiagonal*zRhs-mixed*xRhs)/determinant;
      const pitch=T.MathUtils.clamp(rawPitch,-.13,.13), roll=T.MathUtils.clamp(rawRoll,-.09,.09);
      const yaw=T.MathUtils.clamp((by-xy*rawPitch-yz*rawRoll)/yy,-.19,.19);
      frame.quaternion.premultiply(increment.setFromAxisAngle(axisX,pitch));
      frame.quaternion.premultiply(increment.setFromAxisAngle(axisY,yaw));
      frame.quaternion.premultiply(increment.setFromAxisAngle(axisZ,roll));
      frame.updateMatrix();
      frame.position.add(before.sub(probe.copy(pivot).applyMatrix4(frame.matrix)));
    }
    frame.updateMatrix();
  }

  const joints = [];
  sternum.updateMatrix();
  for (const arm of arms) {
    const side = arm.side;
    const shoulder = vector(side * 1.04, .83, .02);
    const scapula = parts.scapulae.find(item => item.side === side).node;
    scapula.position.set(side * .64, .53, -.36);
    scapula.rotation.set(0, -side * .20, 0);
    scapula.updateMatrix();
    const toScapula = scapula.matrix.clone().invert();
    clear(scapula);
    const blade = add(scapula, 'scapula', parts.scapulaMaterial, side);
    blade.geometry.applyMatrix4(toScapula);
    // Landmark frames come from the same atlas assembly as the surfaces.
    const headCentre = shoulder.clone().applyMatrix4(toScapula);
    const acromion = vector(side * .9279, .9719, -.0312).applyMatrix4(toScapula);
    const sternoclavicular = vector(side * .0708, .7408, .11408).applyMatrix4(sternum.matrix.clone().invert());

    arm.clavicle.geometry.dispose();
    arm.clavicle.geometry = geometry('clavicle', side);
    arm.clavicle.name = 'BodyParts3D clavicle';
    const elbow = vector(side * .16, -1.06, .04), wrist = vector(side * .08, -1.91, .18);
    clear(arm.node);
    mountSegment(arm.node, ['humerus'], vector(0, 0, 0), elbow, parts.contextMaterial, side);
    mountSegment(arm.node, ['radius', 'ulna'], elbow, wrist, parts.contextMaterial, side);
    const hand = add(arm.node, 'handOpen', parts.contextMaterial, side);
    hand.position.copy(wrist);

    const exercise = exArms.find(item => item.side === side);
    for (const group of [exercise.upper, exercise.fore, exercise.hand, exercise.clavicle]) clear(group);
    add(exercise.upper, 'humerus', parts.boneMaterial, side);
    add(exercise.fore, 'radius', parts.boneMaterial, side);
    add(exercise.fore, 'ulna', parts.boneMaterial, side);
    const exerciseHand = add(exercise.hand, 'handGrip', parts.boneMaterial, side);
    joints.push({arm, exercise, exerciseHand, scapula, headCentre, acromion, sternoclavicular,
      chest:chestSurface(side), bladePoints:bladeContactPoints(blade.geometry,scapula,side)});
  }
  const flatHands = new Set(['pushup', 'tension_pushup', 'tension_cat', 'lunge', 'tension_pogo']);
  const joint = new T.Vector3(), target = new T.Vector3(), start = new T.Vector3(), end = new T.Vector3();
  const armAxis = new T.Vector3(), forearmAxis = new T.Vector3(), hinge = new T.Vector3(), forward = new T.Vector3();
  const basis = new T.Matrix4(), rotation = new T.Quaternion();
  function orientElbow(upper, forearm, wrist) {
    // The ulna bends around the humeral trochlea. Preserve this hinge axis
    // when the exercise turns the arm into a different movement plane.
    armAxis.subVectors(upper.position, forearm.position).normalize();
    forearmAxis.subVectors(forearm.position, wrist.position).normalize();
    hinge.crossVectors(forearmAxis, armAxis);
    // The flexion plane becomes indeterminate near full extension. Fade
    // smoothly back to the unrolled segment frame in that small interval.
    const blend = T.MathUtils.smoothstep(hinge.length(), .035, .115);
    if (blend === 0) return;
    hinge.normalize();
    forward.crossVectors(hinge, armAxis);
    upper.quaternion.slerp(rotation.setFromRotationMatrix(basis.makeBasis(hinge,armAxis,forward)), blend);
    forward.crossVectors(hinge, forearmAxis);
    forearm.quaternion.slerp(rotation.setFromRotationMatrix(basis.makeBasis(hinge,forearmAxis,forward)), blend);
  }
  const fit = function(movement) {
    for (const {arm, exercise, exerciseHand, scapula, headCentre, acromion, sternoclavicular, chest, bladePoints} of joints) {
      scapula.updateMatrix();
      joint.copy(headCentre).applyMatrix4(scapula.matrix);
      if (exerciseArms.visible) {
        orientElbow(exercise.upper, exercise.fore, exercise.hand);
        // The exercise solver fixes the hands on their apparatus. Seat the
        // glenoid at the corresponding shoulder while retaining blade rotation.
        torso.worldToLocal(exercise.upper.getWorldPosition(target));
        scapula.position.add(target.sub(joint));
        scapula.updateMatrix();
      } else {
        arm.node.position.copy(joint);
      }
      if (scapula.visible && torso.visible) seatBlade(scapula,headCentre,chest,bladePoints);
      arm.clavicle.visible = exerciseArms.visible || scapula.visible || arm.node.visible;
      sternum.updateMatrix();
      start.copy(sternoclavicular).applyMatrix4(sternum.matrix);
      end.copy(acromion).applyMatrix4(scapula.matrix).sub(start);
      arm.clavicle.position.copy(start);
      arm.clavicle.scale.y = end.length();
      arm.clavicle.quaternion.setFromUnitVectors(down, end.normalize());
      exerciseHand.geometry = geometry(flatHands.has(movement) ? 'handOpen' : 'handGrip', arm.side);
    }
  };
  fit.dispose = () => {
    // The scene owns all mounted geometry. Only a currently inactive grip
    // surface can fall outside the viewer's normal disposal traversal.
    for (const {arm, exerciseHand} of joints) {
      const grip = geometry('handGrip', arm.side);
      if (exerciseHand.geometry !== grip) grip.dispose();
    }
  };
  return fit;
};
})();
